import { SvgEditor } from "../../../svg-editor/src/document/SvgEditor"
import { isSvgRegionElement } from "../../../mapsvg/Region/svgRegion"
export async function createNativeSvgEditor(
  options: Record<string, unknown>,
  params: {
    signal: AbortSignal
    svgFileLastChanged?: number
    load?: (request: () => Promise<string>) => Promise<string>
  },
): Promise<SvgEditor> {
  if (typeof options.source !== "string" || !options.source)
    throw new Error("Choose an SVG file first.")
  const url = new URL(options.source, document.baseURI)
  if (url.origin !== window.location.origin || !/^https?:$/.test(url.protocol))
    throw new Error("The SVG editor requires a same-origin SVG file.")
  if (params.svgFileLastChanged) url.searchParams.set("version", String(params.svgFileLastChanged))
  const controller = new AbortController(),
    abort = () => controller.abort(params.signal.reason)
  params.signal.addEventListener("abort", abort, { once: true })
  if (params.signal.aborted) abort()
  const timeout = setTimeout(
    () => controller.abort(new Error("The SVG file took too long to load.")),
    30000,
  )
  try {
    const request = async () => {
      const response = await fetch(url, {
        credentials: "same-origin",
        cache: "no-store",
        signal: controller.signal,
      })
      if (!response.ok)
        throw Object.assign(new Error(`The SVG file could not load (${response.status}).`), {
          status: response.status,
        })
      return response.text()
    }
    const xml = await (params.load ? params.load(request) : request())
    if (controller.signal.aborted) throw controller.signal.reason
    const prefix = typeof options.regionPrefix === "string" ? options.regionPrefix : ""
    return new SvgEditor(xml, (element) => isSvgRegionElement(element, prefix), prefix)
  } finally {
    clearTimeout(timeout)
    params.signal.removeEventListener("abort", abort)
  }
}
