import type { EditorSnapshot, EditorState, RegionPredicate, TreeEntry } from "../types"
import { SVG_NS } from "../types"
import { parsePath, parsePoints } from "../geometry/path"
import { History } from "./history"
import { isElement, nodes, parseSvg, previewClone, serializeSvg, writeAttribute } from "./xml"

/** Framework-independent authoring document. Rendered SVG is always a disposable clone. */
export class SvgEditor {
  document: XMLDocument
  private identities = new WeakMap<Node, string>()
  private byKey = new Map<string, Node>()
  private nextKey = 0
  private listeners = new Set<() => void>()
  private history = new History()
  private before: EditorSnapshot | null = null
  private original: string
  private originalGeometry: string
  private state: EditorState = {
    revision: 0,
    selected: null,
    canUndo: false,
    canRedo: false,
    dirty: false,
  }
  private disposed = false
  constructor(
    xml: string,
    readonly isRegion: RegionPredicate = () => false,
    readonly idPrefix = "",
  ) {
    this.document = parseSvg(xml)
    this.index()
    this.original = this.exportSvg()
    this.originalGeometry = this.geometry()
  }
  get root() {
    return this.document.documentElement
  }
  get geometryChanged() {
    return this.geometry() !== this.originalGeometry
  }
  private geometry() {
    return ["width", "height", "viewBox"]
      .map((name) => this.root.getAttribute(name) ?? "")
      .join("\n")
  }
  getState = () => this.state
  subscribe = (listener: () => void) => {
    this.listeners.add(listener)
    return () => {
      this.listeners.delete(listener)
    }
  }
  key = (node: Node) => {
    let key = this.identities.get(node)
    if (!key) {
      key = `n${++this.nextKey}`
      this.identities.set(node, key)
      this.byKey.set(key, node)
    }
    return key
  }
  node(key: string | null = this.state.selected): Node | null {
    return key ? (this.byKey.get(key) ?? null) : null
  }
  element(key = this.state.selected): Element | null {
    const node = this.node(key)
    return isElement(node) ? node : null
  }
  private index(keys?: string[]) {
    this.identities = new WeakMap()
    this.byKey.clear()
    nodes(this.root).forEach((node, i) => {
      if (keys?.[i]) {
        this.identities.set(node, keys[i])
        this.byKey.set(keys[i], node)
      } else this.key(node)
    })
  }
  private emit(changed = false) {
    if (this.disposed) return
    this.state = {
      ...this.state,
      revision: this.state.revision + (changed ? 1 : 0),
      canUndo: this.history.canUndo,
      canRedo: this.history.canRedo,
      dirty: this.exportSvg() !== this.original,
    }
    this.listeners.forEach((listener) => listener())
  }
  select(key: string | null) {
    if (key && !this.byKey.has(key)) return
    if (key === this.state.selected) return
    this.state = { ...this.state, selected: key }
    this.emit()
  }
  exportSvg() {
    return serializeSvg(this.document)
  }
  clonePreview() {
    return previewClone(this.root, this.key)
  }
  snapshot(): EditorSnapshot {
    return {
      xml: this.exportSvg(),
      keys: nodes(this.root).map(this.key),
      selected: this.state.selected,
    }
  }
  private restore(snapshot: EditorSnapshot) {
    this.document = parseSvg(snapshot.xml)
    this.index(snapshot.keys)
    this.state = {
      ...this.state,
      selected: snapshot.selected && this.byKey.has(snapshot.selected) ? snapshot.selected : null,
    }
  }
  begin() {
    if (this.before) throw new Error("An SVG edit is already in progress.")
    this.before = this.snapshot()
  }
  commit(label: string) {
    if (!this.before) return
    const before = this.before
    this.before = null
    this.history.push(label, before, this.snapshot())
    this.emit(true)
  }
  cancel() {
    if (!this.before) return
    const before = this.before
    this.before = null
    // A click without movement must retain DOM identity in the preview, so the
    // browser can deliver a subsequent double-click to the same path/handle.
    if (this.exportSvg() === before.xml) {
      if (this.state.selected !== before.selected) this.select(before.selected)
      return
    }
    this.restore(before)
    this.emit(true)
  }
  change(label: string, mutation: () => void) {
    this.begin()
    try {
      mutation()
      this.commit(label)
    } catch (error) {
      this.cancel()
      throw error
    }
  }
  undo() {
    this.cancel()
    const previous = this.history.undo()
    if (previous) {
      this.restore(previous)
      this.emit(true)
    }
  }
  redo() {
    this.cancel()
    const next = this.history.redo()
    if (next) {
      this.restore(next)
      this.emit(true)
    }
  }
  setAttribute(key: string, name: string, value: string | null) {
    const element = this.element(key)
    if (!element) throw new Error("Select an XML element.")
    if (name === "id" && value) {
      if (/\s/.test(value)) throw new Error("An SVG ID cannot contain spaces.")
      if (
        [this.root, ...Array.from(this.root.querySelectorAll("[id]"))].some(
          (other) => other !== element && other.id === value,
        )
      )
        throw new Error("This SVG ID is already in use.")
    }
    if (name === "d" && value) parsePath(value)
    if (name === "points" && value) parsePoints(value)
    if (name === "viewBox" && value) {
      const v = value
        .trim()
        .split(/[\s,]+/)
        .map(Number)
      if (v.length !== 4 || v.some((n) => !Number.isFinite(n)) || v[2] <= 0 || v[3] <= 0)
        throw new Error("Use x y width height, with positive width and height.")
    }
    if (name === "xmlns" && value !== SVG_NS)
      throw new Error("The SVG namespace must be preserved.")
    writeAttribute(element, name, value)
  }
  updateAttribute(key: string, name: string, value: string | null) {
    this.change(`Set ${name}`, () => this.setAttribute(key, name, value))
  }
  updateText(key: string, value: string) {
    this.change("Edit text", () => {
      const node = this.node(key)
      if (!node) return
      if (isElement(node)) {
        if (Array.from(node.childNodes).some(isElement))
          throw new Error("Select a child text node to preserve nested elements.")
        node.textContent = value
        nodes(node).forEach(this.key)
      } else {
        if (node.nodeType === 8 && (/--/.test(value) || value.endsWith("-")))
          throw new Error("XML comments cannot contain -- or end with -.")
        if (node.nodeType === 4 && value.includes("]]>"))
          throw new Error("CDATA cannot contain ]]>. ")
        node.nodeValue = value
      }
    })
  }
  deleteNode(key = this.state.selected) {
    const node = this.node(key)
    if (!node || node === this.root) return
    this.change("Delete node", () => {
      for (const child of nodes(node)) this.byKey.delete(this.key(child))
      node.parentNode?.removeChild(node)
      this.state = { ...this.state, selected: null }
    })
  }
  addPath(d: string) {
    parsePath(d)
    let id = 1
    const ids = new Set(
      [this.root, ...Array.from(this.root.querySelectorAll("[id]"))].map((e) => e.id),
    )
    while (ids.has(`${this.idPrefix}region_${id}`)) id++
    this.change("Draw region", () => {
      const path = this.document.createElementNS(SVG_NS, "path")
      path.setAttribute("id", `${this.idPrefix}region_${id}`)
      path.setAttribute("d", d)
      path.setAttribute("fill", "#cbd5e1")
      path.setAttribute("stroke", "#64748b")
      path.setAttribute("stroke-width", "1")
      this.root.appendChild(path)
      this.state = { ...this.state, selected: this.key(path) }
    })
  }
  tree(): TreeEntry[] {
    const walk = (node: Node, parent: string | null): TreeEntry | null => {
      if (!isElement(node) && !node.nodeValue?.trim()) return null
      const key = this.key(node)
      return {
        key,
        name: isElement(node)
          ? node.tagName
          : node.nodeType === 8
            ? "#comment"
            : node.nodeType === 4
              ? "#cdata"
              : "#text",
        id: isElement(node) ? (node.getAttribute("id") ?? "") : "",
        text: isElement(node) ? "" : (node.nodeValue ?? ""),
        region: isElement(node) && this.isRegion(node),
        parent,
        children: Array.from(node.childNodes)
          .map((child) => walk(child, key))
          .filter((entry): entry is TreeEntry => entry !== null),
      }
    }
    const root = walk(this.root, null)
    return root ? [root] : []
  }
  dispose() {
    this.disposed = true
    this.before = null
    this.history.clear()
    this.listeners.clear()
    this.byKey.clear()
  }
}
