import type { EditorSnapshot } from "../types"
type Entry = { label: string; before: EditorSnapshot; after: EditorSnapshot }
/** One entry per completed gesture or committed form edit, independent of SVG IDs. */
export class History {
  private entries: Entry[] = []
  private cursor = 0
  get canUndo() {
    return this.cursor > 0
  }
  get canRedo() {
    return this.cursor < this.entries.length
  }
  push(label: string, before: EditorSnapshot, after: EditorSnapshot) {
    if (before.xml === after.xml) return
    this.entries.splice(this.cursor)
    this.entries.push({ label, before, after })
    let bytes = this.entries.reduce(
      (sum, entry) => sum + (entry.before.xml.length + entry.after.xml.length) * 2,
      0,
    )
    while (this.entries.length > 1 && (this.entries.length > 80 || bytes > 24 * 1024 * 1024)) {
      const removed = this.entries.shift()!
      bytes -= (removed.before.xml.length + removed.after.xml.length) * 2
    }
    this.cursor = this.entries.length
  }
  undo() {
    return this.canUndo ? this.entries[--this.cursor].before : null
  }
  redo() {
    return this.canRedo ? this.entries[this.cursor++].after : null
  }
  clear() {
    this.entries = []
    this.cursor = 0
  }
}
